SELECT id, symbol, status, UNIX_TIMESTAMP(started_at) AS started_epoch, UNIX_TIMESTAMP(last_evidence_at) AS last_ev_epoch, anchor_entry_price, best_entry_price, evidence_count, buy_count, watch_count, neutral_count, bearish_count, average_signal_score, average_confidence, peak_decision, UNIX_TIMESTAMP(peak_observed_at) AS peak_epoch, UNIX_TIMESTAMP(executed_at) AS exec_epoch, UNIX_TIMESTAMP(updated_at) AS upd_epoch FROM crypto_ai.execution_opportunity WHERE id IN (35535,36524,37621,37952,39062,40290) ORDER BY id LIMIT 10;